        private readonly ulong[] _codes;

        // All four 90-degree rotations of every code, laid out as [id * 4 + rotation]. Built
        // once per dictionary: identification has to try every rotation of every marker for each
        // candidate, because a printed tag can be approached from any side.
        private readonly ulong[] _rotatedCodes;

        private static readonly Dictionary<ArucoDictionaryName, ArucoDictionary> k_Cache =
            new Dictionary<ArucoDictionaryName, ArucoDictionary>();

        public ArucoDictionaryName Name { get; }

        // Cells per side of the code grid, excluding the black border (4 for a 4x4 dictionary)
        public int GridSize { get; }

        // How many wrong bits a candidate may have and still be accepted as a given id. This is
        // OpenCV's own maxCorrectionBits for the dictionary: (minimum inter-marker distance - 1)
        // / 2, the largest budget that still cannot turn one valid marker into a different one.
        public int MaxCorrectionBits { get; }

        public int MarkerCount => _codes.Length;

        public int BitCount => GridSize * GridSize;

        private ArucoDictionary(ArucoDictionaryName name, int gridSize, int maxCorrectionBits,
            ulong[] codes)
        {
            Name = name;
            GridSize = gridSize;
            MaxCorrectionBits = maxCorrectionBits;
            _codes = codes;

            _rotatedCodes = new ulong[codes.Length * 4];
            for (int id = 0; id < codes.Length; id++)
            {
                ulong code = codes[id];
                for (int rotation = 0; rotation < 4; rotation++)
                {
                    _rotatedCodes[id * 4 + rotation] = code;
                    code = RotateClockwise(code, gridSize);
                }
            }
        }

        public static ArucoDictionary Get(ArucoDictionaryName name)
        {
            if (k_Cache.TryGetValue(name, out var cached))
                return cached;

            ArucoDictionary dictionary;
            switch (name)
            {
                case ArucoDictionaryName.Dict4x4_50:
                    dictionary = new ArucoDictionary(name, 4, 1, k_Dict4x4_50);
                    break;
                case ArucoDictionaryName.Dict4x4_250:
                    dictionary = new ArucoDictionary(name, 4, 1, k_Dict4x4_250);
                    break;
                case ArucoDictionaryName.Dict5x5_250:
                    dictionary = new ArucoDictionary(name, 5, 2, k_Dict5x5_250);
                    break;
                case ArucoDictionaryName.Dict6x6_250:
                    dictionary = new ArucoDictionary(name, 6, 5, k_Dict6x6_250);
                    break;
                default:
                    throw new ArgumentOutOfRangeException(nameof(name), name,
                        "Unknown ArUco dictionary");
            }

            k_Cache[name] = dictionary;
            return dictionary;
        }

        // The canonical code for an id, for drawing a printable tag
        public ulong GetCode(int id)
        {
            if (id < 0 || id >= _codes.Length)
                throw new ArgumentOutOfRangeException(nameof(id), id,
                    $"{Name} has ids 0..{_codes.Length - 1}");
            return _codes[id];
        }

        public bool IsBitSet(ulong code, int row, int column)
        {
            int shift = BitCount - 1 - (row * GridSize + column);
            return ((code >> shift) & 1UL) != 0UL;
        }

        // Turn an observed grid of bits into a marker id.
        //
        // `rotation` is how many 90-degree CLOCKWISE turns of the observed grid line it up with
        // the printed one, which is also what tells the caller which observed corner is the
        // marker's top-left: canonical corner j is observed corner (j - rotation) mod 4, for
        // corners listed clockwise in image space. Without that the id would be right while the
        // pose came out yawed by a multiple of 90 degrees - the classic way a marker-based
        // calibration ends up placing a robot sideways.
        public bool TryIdentify(ulong observed, out int id, out int rotation, out int errors)
        {
            id = -1;
            rotation = 0;
            errors = int.MaxValue;

            for (int candidate = 0; candidate < _codes.Length; candidate++)
            {
                for (int turn = 0; turn < 4; turn++)
                {
                    int distance = HammingDistance(observed, _rotatedCodes[candidate * 4 + turn]);
                    if (distance >= errors)
                        continue;

                    errors = distance;
                    id = candidate;
                    // _rotatedCodes[id * 4 + turn] is the printed code turned CW `turn` times,
                    // and it matched what we saw - so turning what we saw CW (4 - turn) times
                    // gets back to the printed orientation.
                    rotation = (4 - turn) & 3;

                    if (distance == 0)
                        return true;
                }
            }

            if (errors > MaxCorrectionBits)
            {
                id = -1;
                rotation = 0;
                errors = int.MaxValue;
                return false;
            }

            return true;
        }

        // 90 degrees clockwise: the cell at (row, column) moves to (column, GridSize - 1 - row)
        public static ulong RotateClockwise(ulong code, int gridSize)
        {
            int bits = gridSize * gridSize;
            ulong result = 0UL;
            for (int row = 0; row < gridSize; row++)
            {
                for (int column = 0; column < gridSize; column++)
                {
                    int sourceShift = bits - 1 - (row * gridSize + column);
                    if (((code >> sourceShift) & 1UL) == 0UL)
                        continue;

                    int destinationShift = bits - 1 - (column * gridSize + (gridSize - 1 - row));
                    result |= 1UL << destinationShift;
                }
            }
            return result;
        }

        // Mirrored left-to-right: the cell at (row, column) moves to (row, GridSize - 1 - column)
        public static ulong MirrorHorizontal(ulong code, int gridSize)
        {
            int bits = gridSize * gridSize;
            ulong result = 0UL;
            for (int row = 0; row < gridSize; row++)
            {
                for (int column = 0; column < gridSize; column++)
                {
                    int sourceShift = bits - 1 - (row * gridSize + column);
                    if (((code >> sourceShift) & 1UL) == 0UL)
                        continue;

                    int destinationShift = bits - 1 - (row * gridSize + (gridSize - 1 - column));
                    result |= 1UL << destinationShift;
                }
            }
            return result;
        }

        // DIAGNOSIS ONLY - never a route to accepting a marker.
        //
        // TryIdentify searches the four ROTATIONS, because that is the only ambiguity a
        // correctly-oriented camera can produce. A vertically flipped image is a REFLECTION,
        // which no amount of rotation reaches, so every tag in a mirrored feed decodes as
        // nothing at all. Downstream that is indistinguishable from a tag printed from the
        // wrong dictionary, and it sends the user off to reprint a tag that was fine.
        //
        // A mirrored pose would be wrong in a way nothing later could detect, so this answers
        // the diagnostic question only: would this code have been a tag, had the image not been
        // reflected? The caller reports that and stops.
        public bool IdentifiesWhenMirrored(ulong observed)
        {
            ulong mirrored = MirrorHorizontal(observed, GridSize);
            return TryIdentify(mirrored, out _, out _, out _);
        }

        private static int HammingDistance(ulong a, ulong b)
        {
            ulong diff = a ^ b;
            int count = 0;
            while (diff != 0UL)
            {
                diff &= diff - 1UL;
                count++;
            }
            return count;
        }
    }
}
